# --- match_albums.py:2273
def folder_reading(album_folder):
    """FLD-2: a folder name read as "Artist - Album": (head, rest, year), else None.
    The leading year ("1997 - ...") is skipped, as read_album does, and a year between the two
    ("Artist - 1997 - Album") is the year; one after the album ("Album - 2010", "Album (2010)") is
    taken out of the rest, never made the year. Only " - " (or " – ") splits: "Jay-Z" is one
    name. Never a head that is a year, a disc word ("CD1 - ...", "Vol. 2 - ..."), a catalogue
    number, numbers alone or Various Artists ("VA - ..."); never an empty rest."""
    name = str(album_folder or "").strip()
    lead = re.match(r"\s*(\d{4})\s*[-–]\s*(.*)", name)
    year = int(lead.group(1)) if lead else 0
    name = lead.group(2) if lead else name
    parts = re.split(r"\s+[-–]\s+", name, maxsplit=1)
    if len(parts) != 2:
        return None
    head, rest = parts[0].strip(), parts[1].strip()
    mid = re.match(r"(\d{4})\s+[-–]\s+(.+)$", rest)
    if mid:
        year, rest = year or int(mid.group(1)), mid.group(2).strip()
    # a year after the album ("Album - 2010", "Album (2010)") is taken out of the title searched,
    # never made the album's year: it is as often a reissue's ("(2009)" of a 1997 album), and a
    # year that disagrees would lower a sure pick (YR-1). A range keeps its two years ("The Early
    # Years 1965 - 1972": no year cut off).
    tail = re.match(r"(.+?)\s*(?:\s[-–]\s+(\d{4})|[\(\[](\d{4})[\)\]])\s*$", rest)
    if tail and mc.fold(tail.group(1)) and not (tail.group(2) and re.search(r"\b\d{4}$", tail.group(1))):
        rest = tail.group(1).strip()
    if not mc.fold(head) or not mc.fold(rest):
        return None
    if re.fullmatch(r"[\d\W_]+", head) or _DISC_HEAD.fullmatch(head) or _VARIOUS_HEAD.fullmatch(head):
        return None
    if mc.catno_hints(head) or mc.catno_hints(f"[{head}]"):
        return None
    return head, rest, year


# --- match_albums.py:3159
_SACD_NAME = re.compile(r"(?<![A-Za-z0-9])(?:SACD|DS[DT]\d+)(?![A-Za-z])", re.I)   # ("DSD64", never "DST")


# --- match_albums.py:3160
_SACD_TOOL = re.compile(r"SACD[- ]?Ripper|sacd_extract|SACD[- ]?Extract|ISO2DSD|DSD2PCM|SACD ISO", re.I)


# --- match_albums.py:3163
def sacd_marks(album_dir, album_folder) -> str:
    """MED-13: what says the copy was ripped from an SACD, else "": "SACD" or "DSD64" in the
    folder's name, or the log an SACD ripping tool wrote in the folder ("misc/sacd_log.txt":
    SACD-Ripper, sacd_extract, ISO2DSD) - which stays when the folder is renamed. Only small
    text files are read, and only those named for the SACD or a log."""
    if _SACD_NAME.search(str(album_folder or "")):
        return "folder name"
    try:
        found = [p for p in Path(album_dir).rglob("*") if p.suffix.lower() in (".log", ".txt")
                 and ("sacd" in p.name.lower() or p.suffix.lower() == ".log")][:20]
    except OSError:
        return ""
    for p in found:
        try:
            if p.stat().st_size > 512 * 1024:
                continue
            with open(p, "rb") as fh:
                head = fh.read(4096)
        except OSError:
            continue
        text = head.decode("utf-16", "ignore") if head[:2] in (b"\xff\xfe", b"\xfe\xff") else \
            head.decode("utf-8", "ignore")
        if _SACD_TOOL.search(text):
            return f"an SACD rip log ({p.name})"
    return ""


# --- match_albums.py:3476
# An Enhanced CD (CD-Extra) has its data track in a second session, 11400 sectors after
# the audio: MusicBrainz's disc ID covers the audio only, ending 11400 sectors before it.
SESSION_GAP = 11400


# --- match_albums.py:3479
def audio_session(tracks):
    """The audio tracks of a log's TOC table [(start, end)] and the sector the audio
    ends at (its lead-out, from 0): an Enhanced CD's last track is its data track."""
    if len(tracks) >= 2 and tracks[-1][0] - tracks[-2][1] - 1 >= SESSION_GAP:
        return tracks[:-1], tracks[-1][0] - SESSION_GAP
    return tracks, tracks[-1][1] + 1


# --- match_albums.py:3487
_LOG_TOC_ROW = re.compile(r"^\s*(\d{1,2})\s*\|\s*[\d:.]+\s*\|\s*[\d:.]+\s*\|\s*(\d+)\s*\|\s*(\d+)\s*$", re.M)


# --- match_albums.py:3490
def _read_log(path):
    raw = Path(path).read_bytes()[:400000]
    for enc in ("utf-16",) if raw[:2] in (b"\xff\xfe", b"\xfe\xff") else ("utf-8", "cp1252"):
        try:
            return raw.decode(enc)
        except UnicodeDecodeError:
            continue
    return raw.decode("latin-1", "ignore")


# --- match_albums.py:3500
def log_tocs(album_dir):
    """Tables of contents from the rip logs next to the music (EAC, XLD): the
    exact disc that was ripped, whatever the files were converted to since."""
    out = []
    for log in rip_logs(album_dir):
        if log["toc"] and log["toc"] not in out:
            out.append(log["toc"])
    return {i + 1: toc for i, toc in enumerate(out)}


# --- match_albums.py:3512
# The disc a log was made of, on its own line near the top: "Jesu / Conqueror (Japanese Bonus
# Disc)" (EAC, XLD; in any language of the program)
_LOG_HEADER = re.compile(r"^(\S[^\r\n:]*?)\s+/\s+(\S[^\r\n]*?)\s*$")


# --- match_albums.py:3513
_WIN_PATH = re.compile(r"(?<![A-Za-z])[A-Za-z]:\\[^\r\n\t\"]+")


# --- match_albums.py:3516
# where a log names the file it wrote ("     Filename D:\\EAC\\...\\01.wav", "Output file: ..."),
# a ripped file's own extension, and the parts of a path that are the program's
_OUTPUT_LINE = re.compile(r"(?i)\b(?:file\s*name|dateiname|nom\s+de\s+fichier|имя\s+файла|output)\b")


# --- match_albums.py:3517
_AUDIO_PATH = re.compile(r"(?i)\.(?:wav|flac|ape|wv|mp3|m4a|aiff?|tak|ogg|opus)\s*$")


# --- match_albums.py:3518
_PROGRAM_PART = re.compile(r"(?i)program\s*files|\(x(?:86|64)\)|^x(?:86|64)$|exact\s*audio\s*copy|\.exe$")


# --- match_albums.py:3521
def _log_toc(text):
    """The TOC of one log's text in MusicBrainz's form, and whether its disc had a data
    track (an Enhanced CD), or ("", False)."""
    if "TOC" not in text and "toc" not in text:
        return "", False
    rows = [(int(n), int(s), int(e)) for n, s, e in _LOG_TOC_ROW.findall(text)]
    seen, tracks = set(), []
    for n, s, e in rows:                       # the TOC table only (first occurrence of each track)
        if n in seen:
            break
        seen.add(n)
        tracks.append((s, e))
    if not 1 <= len(tracks) <= 99:
        return "", False
    audio, leadout = audio_session(tracks)
    offsets = [s + 150 for s, _e in audio]
    return " ".join(str(x) for x in [1, len(audio), leadout + 150] + offsets), len(audio) < len(tracks)


# --- match_albums.py:3540
def _log_header(text):
    """(artist, album) of the disc the log names in its first lines, or None."""
    lines = [l for l in text.splitlines()[:12] if l.strip()]
    for line in lines[:6]:
        m = _LOG_HEADER.match(line.strip())
        if m and not re.search(r"\d{1,2}:\d{2}|\\|https?:", line):
            return m.group(1).strip(), m.group(2).strip()
    return None


# --- match_albums.py:3550
def _path_codes(text, name):
    """Catalogue numbers the ripper typed into the folders it ripped to ("D:\\EAC\\... (Prosthetic
    - 7930183432)\\...wav", "...\\2014-Metal Mind [Poland, MASS CD 1491 DG]\\...") and into the
    log's own name ("Candlemass (Metal Mind).log"): written like a folder name, read as one.
    Only the paths of the files ripped count: the encoder's ("C:\\Program Files (x86)\\Exact Audio
    Copy\\Flac\\flac.exe") names the program, and its "(x86)" is no number."""
    parts = [name]
    for m in _WIN_PATH.finditer(text):
        path = m.group(0).strip()
        line = text[text.rfind("\n", 0, m.start()) + 1:m.start()]
        if not (_OUTPUT_LINE.search(line) or _AUDIO_PATH.search(path)):
            continue
        folders = re.split(r"[\\/]", path)[1:]
        if _AUDIO_PATH.search(path):             # (a track's own name is its title: "... (MC 900 Ft. Jesus Mix).wav")
            folders = folders[:-1]
        parts += [x for x in folders if x and not _PROGRAM_PART.search(x)]
    out = []
    for part in parts:
        for c in mc.catno_hints(part):
            if c not in out:
                out.append(c)
    return out


# --- match_albums.py:3574
def rip_logs(album_dir):
    """Every rip log under the album folder: {"path", "toc" (MusicBrainz form, "" when it has
    none), "data_track" (an Enhanced CD's), "header" ((artist, album) or None), "codes"
    (catalogue numbers in its output paths and its name), "crcs" (its CRC values), "out_parts"
    (the folders of the files it wrote)}, in natural order."""
    out = []
    for p in sorted(Path(album_dir).rglob("*.log"), key=lambda p: _natural_key(str(p))):
        try:
            text = _read_log(p)
        except OSError:
            continue
        toc, data = _log_toc(text)
        out.append({"path": str(p), "toc": toc, "data_track": data, "header": _log_header(text),
                    "codes": _path_codes(text, p.stem), "crcs": set(re.findall(r"\bCRC\s+([0-9A-F]{8})\b", text)),
                    "out_parts": _output_parts(text),
                    # DAT-3: the year the ripper made it (EAC, XLD)
                    "year": log_date_year(text)})
    return out


# --- match_albums.py:3600
# DAT-3: the date a ripping program wrote at the top of its log. EAC, in any of its languages:
# "EAC extraction logfile from 27. August 2005, 15:28 for CD", "EAC Auslese-Logdatei vom 27.
# August 2005", "Отчёт EAC об извлечении, выполненном 27. августа 2005" (day, month, year; also
# CUERipper's logs, written in EAC's form). Never EAC 1.x's first line "Exact Audio Copy V1.0
# beta 3 from 29. August 2011": that is the program's own build date. XLD: "XLD extraction
# logfile from 2008-09-24 22:07:47 +0900". A checker's log (auCDtect, audiochecker) has neither.
_EAC_DATE = re.compile(r"(?<!\d)\d{1,2}\.\s*\S{1,15}?\s+((?:19|20)\d{2})(?!\d)")


# --- match_albums.py:3601
_XLD_DATE = re.compile(r"^\s*XLD extraction logfile from\s+((?:19|20)\d{2})-\d{2}-\d{2}\b", re.M)


# --- match_albums.py:3602
_EAC_WORD = re.compile(r"(?<![A-Za-z])EAC(?![A-Za-z])")


# --- match_albums.py:3605
def log_date_year(text):
    """DAT-3: the year an EAC or XLD rip log says it was made, from its first lines, or None
    (another program's log, no date, or a year no ripper could have written: before EAC
    existed, or in the future)."""
    head = [l for l in str(text or "").splitlines()[:12] if l.strip()][:6]
    year = None
    m = _XLD_DATE.search("\n".join(head))
    if m:
        year = int(m.group(1))
    else:
        for line in head:
            if _EAC_WORD.search(line) and not re.search(r"(?i)exact\s+audio\s+copy", line):
                m = _EAC_DATE.search(line)
                if m:
                    year = int(m.group(1))
                    break
    if year is None or not 1998 <= year <= time.localtime().tm_year:
        return None
    return year


# --- match_albums.py:3626
def rip_log_year(album_dir, logs):
    """DAT-3: (the earliest year a rip log of these files was made, its file name), or (None, "").
    A log counts only when it is an EAC or XLD log with a date and it is proven to be of these
    files: its TOC fits them (LOGS are fitting_logs' kept ones, so a TOC there fits), or, with
    no TOC (older EAC), a CUETools report in the folder confirms its CRCs (accurip_confirms).
    A log merely naming files like yours may be another rip's of the same album, and a
    checker's log (auCDtect, audiochecker) has no ripper's date: neither counts."""
    best = (None, "")
    for log in logs:
        y = log.get("year")
        if not y:
            continue
        if (log["toc"] or accurip_confirms(album_dir, log)) and (best[0] is None or y < best[0]):
            best = (y, Path(log["path"]).name)
    return best


# --- match_albums.py:3643
def _output_parts(text):
    """The folders of the files a log says it wrote (its Filename/Output lines), without the
    program's own ("C:\\Lossrip\\Pestilence [2006 - reissue] [CD] Mind Reflections\\...wav")."""
    parts = []
    for m in _WIN_PATH.finditer(text):
        line = text[text.rfind("\n", 0, m.start()) + 1:m.start()]
        if _OUTPUT_LINE.search(line):
            parts += [x for x in re.split(r"[\\/]", m.group(0).strip())[1:-1] if x and not _PROGRAM_PART.search(x)]
    return parts


# --- match_albums.py:3656
# A CUETools report's CRC row: "[CRC32] [W/O NULL]" then the LOG column: "CRC32" or "W/O NULL"
# when the log's CRC is that one, the log's own "[XXXXXXXX]" when it differs
_ACCURIP_ROW = re.compile(r"^\s*(?:--|\d{1,2})\s+[\d.,]+\s+\[([0-9A-F]{8})\]\s+\[([0-9A-F]{8})\]"
                          r"[ \t]*(CRC32|W/O NULL|\[[0-9A-F]{8}\])?", re.M)


# --- match_albums.py:3660
def accurip_confirms(album_dir, log):
    """A CUETools .accurip report in the folder checked this log's CRC against the files:
    one of the log's CRCs is in the report with the LOG column "CRC32" or "W/O NULL", and no
    row shows a log CRC that differs. A log without a TOC (the old EAC kind) is then still
    proven to be of these files (Pestilence - Mind Reflections: CRC 90E183CD)."""
    if not log.get("crcs"):
        return False
    hit = False
    for p in Path(album_dir).rglob("*.accurip"):
        try:
            text = _read_log(p)
        except OSError:
            continue
        for crc32, wo_null, col in _ACCURIP_ROW.findall(text):
            if col.startswith("["):
                return False
            if (col == "CRC32" and crc32 in log["crcs"]) or (col == "W/O NULL" and wo_null in log["crcs"]):
                hit = True
    return hit


# --- match_albums.py:3778
_CDTOC_TAG = re.compile(r"^\s*([0-9A-Fa-f]{1,2})((?:\+[0-9A-Fa-f]+)+)\s*$")


# --- match_albums.py:3781
def cdtoc_tag_toc(value):
    """The CDTOC tag rippers write ("20+96+1937+...+4E6E9": the track count, each track's
    start and the lead-out, in hex sectors with the 150-sector lead-in) in MusicBrainz's
    TOC form ("1 32 321257 150 6455 ..."), or ""."""
    m = _CDTOC_TAG.match(str(value or ""))
    if not m:
        return ""
    n = int(m.group(1), 16)
    nums = [int(x, 16) for x in m.group(2).strip("+").split("+")]
    if not 1 <= n <= 99 or len(nums) != n + 1 or nums != sorted(nums):
        return ""
    return " ".join(str(x) for x in [1, n, nums[-1]] + nums[:-1])


# --- match_albums.py:4043
def mb_discid(toc):
    """The MusicBrainz disc ID of a table of contents ("1 N leadout off1 ... offN")."""
    import base64
    import hashlib
    nums = [int(x) for x in toc.split()]
    first, last, leadout, offsets = nums[0], nums[1], nums[2], nums[3:]
    text = f"{first:02X}{last:02X}{leadout:08X}" + "".join(
        f"{(offsets[i] if i < len(offsets) else 0):08X}" for i in range(99))
    digest = hashlib.sha1(text.encode("ascii")).digest()
    return base64.b64encode(digest).decode("ascii").replace("+", ".").replace("/", "_").replace("=", "-")


# --- match_albums.py:4055
def ctdb_toc(toc):
    """The same table of contents in CUETools DB form (sectors from 0, colon separated)."""
    nums = [int(x) for x in toc.split()]
    return ":".join(str(x - 150) for x in nums[3:] + [nums[2]])


# --- match_albums.py:4272
def cue_tocs(album_dir, infos):
    """Tables of contents from cue sheets: track starts from INDEX 01, the end
    from the length of the audio (per-track files are added up in order)."""
    out = []
    secs_by_name = {Path(p).name.casefold(): i["secs"] for p, i in infos if p is not None}
    track_secs = [i["secs"] for _p, i in infos]
    for cue in sorted(Path(album_dir).rglob("*.cue"), key=lambda p: _natural_key(str(p))):
        try:
            text = _read_log(cue)
        except OSError:
            continue
        files, current, starts = [], None, []
        for line in text.splitlines():
            m = re.match(r'\s*FILE\s+"?(.+?)"?\s+(WAVE|FLAC|MP3|AIFF|BINARY)?\s*$', line, re.I)
            if m:
                current = {"name": m.group(1), "tracks": []}
                files.append(current)
                continue
            m = re.match(r"\s*INDEX\s+01\s+(\d+):(\d+):(\d+)", line)
            if m and current is not None:
                current["tracks"].append(int(m.group(1)) * 4500 + int(m.group(2)) * 75 + int(m.group(3)))
        n = sum(len(f["tracks"]) for f in files)
        if not n or n > 99:
            continue
        pos, offsets = 0, []
        ok = True
        for k, f in enumerate(files):
            length = secs_by_name.get(Path(f["name"]).name.casefold())
            if length is None:
                # converted since (names changed): one file per track, in order
                length = track_secs[k] if len(files) == len(track_secs) else None
            if length is None and k < len(files) - 1:
                ok = False
                break
            offsets += [pos + s for s in f["tracks"]]
            if length is None:                         # single-file cue whose file is gone
                ok = False
                break
            pos += round(length * 75)
        if ok and offsets:
            toc = " ".join(str(x) for x in [1, len(offsets), pos + 150] + [o + 150 for o in offsets])
            if toc not in out:
                out.append(toc)
    return {i + 1: toc for i, toc in enumerate(out)}


# --- match_albums.py:5290
_MB_DISCOGS_RE = re.compile(r"discogs\.com/(?:[a-zA-Z-]+/)?release/(\d+)", re.I)


# --- match_albums.py:5311
def mb_linked_discogs_ids(rel):
    """Every Discogs RELEASE id MusicBrainz links this release to, in the order listed
    (several when Discogs lists the pressing twice). Master links are ignored: a master is
    the work, not a pressing. match_core.same_pressing reads them all: a Discogs release
    not among them is another pressing for MusicBrainz."""
    out = []
    for r in rel.get("relations") or []:
        if r.get("target-type") != "url":
            continue
        m = _MB_DISCOGS_RE.search((r.get("url") or {}).get("resource") or "")
        if m and m.group(1) not in out:
            out.append(m.group(1))
    return out


# --- match_albums.py:5469
def _genre_names(genres):
    """MusicBrainz genres ([{"name": ...}]) or Discogs ones (strings): their names, once each, in order."""
    out = []
    for g in genres:
        name = str((g.get("name") if isinstance(g, dict) else g) or "").strip()
        if name and name.casefold() not in {x.casefold() for x in out}:
            out.append(name)
    return out


# --- match_albums.py:5846
# --------------------------------------------------------------------------
# Discogs
# --------------------------------------------------------------------------
_POS_DISC = re.compile(r"^\s*(?:[A-Za-z]{1,4})?(\d+)\s*[-.]\s*\d+")


# --- match_albums.py:5849
def _row_kind(e) -> str:
    return str(e.get("type_") or e.get("type") or "track").strip().casefold()


# --- match_albums.py:5855
# a movement's place within its work: "7.I", "7-II", "7a" - letters or roman numerals, never a
# number ("2-2", "1.7": a disc's track)
_MOVEMENT_REST = re.compile(r"^\s*(?:[.\-]\s*[ivxlc]+|\.?\s*[a-z])\s*$", re.I)   # (never a number: "2-2")


# --- match_albums.py:5858
def _movement_of(position, parent) -> bool:
    """POSITION numbers a movement of the track at PARENT ("7.I", "7a" of "7"; never "10" of "1")."""
    p, s = str(parent or "").strip(), str(position or "").strip()
    # (only a track's own number has movements: "7", "1-7", "A7" - never "7.I", whose "7.II" follows)
    return bool(p) and p[-1].isdigit() and s.startswith(p) and bool(_MOVEMENT_REST.match(s[len(p):]))


# --- match_albums.py:5865
def one_track_movements(tracklist, whole_works=False) -> list:
    """TRK-1: a work Discogs lists with its movements under it - an index entry with its own
    length whose sub-tracks list none (Blood, Sweat & Tears - Mirror Image & New City: "Mirror
    Image" 11:09, movements 7a-7d), or a track with its own length followed by rows of its
    movements without lengths ("Symphony For The Devil" 7:49, then 7.I, 7.II, 7.III, on BS&T 3)
    - is ONE track of the disc: the movements are index points or the sleeve's headings, not
    tracks. Any movement listing its own length keeps the work as listed (each its own track,
    never half merged).
    Every reader of a Discogs tracklist (the matcher, the tags written) uses this; applied twice
    it changes nothing."""
    rows = [e for e in tracklist or []]
    out, i = [], 0
    while i < len(rows):
        e = rows[i]
        if not isinstance(e, dict):
            out.append(e)
            i += 1
            continue
        kind = _row_kind(e)
        if kind == "index":
            subs = [s for s in e.get("sub_tracks") or [] if isinstance(s, dict) and _row_kind(s) == "track"]
            # (TRK-5, WHOLE_WORKS: a work listing no length either, its parts lettered as one
            # track's - read so only where your files' discs hold one file per work)
            if (str(e.get("duration") or "").strip() or whole_works) and subs and \
                    not any(str(s.get("duration") or "").strip() for s in subs):
                pos = str(e.get("position") or "").strip()
                if not pos:                          # ("" over 7a-7d: the work is track 7)
                    m = re.match(r"^(.*\d)(?:[.\-]\s*[ivxlc]+|\.?\s*[a-z])\s*$", str(subs[0].get("position") or ""), re.I)
                    pos = m.group(1) if m else ""
                if not pos or not all(_movement_of(s.get("position"), pos) for s in subs):
                    out.append(e)                    # (sub-tracks numbered as tracks: listed as they are)
                    i += 1
                    continue
                one = {k: v for k, v in e.items() if k != "sub_tracks"}
                one.update(type_="track", position=pos)
                if not one.get("artists") and subs[0].get("artists"):
                    one["artists"] = subs[0]["artists"]
                out.append(one)
                i += 1
                continue
        elif kind == "track" and str(e.get("duration") or "").strip():
            j = i + 1
            while (j < len(rows) and isinstance(rows[j], dict) and _row_kind(rows[j]) == "track"
                   and _movement_of(rows[j].get("position"), e.get("position"))):
                j += 1
            out.append(e)
            # (its movements: no tracks of their own - only when NONE lists a length; one that
            # does keeps the work as listed, every row its own track, never half merged)
            if not any(str(r.get("duration") or "").strip() for r in rows[i + 1:j]):
                i = j
            else:
                i += 1
            continue
        out.append(e)
        i += 1
    return out


# --- match_albums.py:5923
def discogs_one_track_movements(rel, whole_works=False):
    """REL with its tracklist read as TRK-1 has it (one_track_movements); REL itself when that
    changes nothing. WHOLE_WORKS: TRK-5's reading too (a work without lengths, one track)."""
    if not isinstance(rel, dict) or not rel.get("tracklist"):
        return rel
    flat = one_track_movements(rel["tracklist"], whole_works)
    return rel if len(flat) == len(rel["tracklist"]) and all(a is b for a, b in zip(flat, rel["tracklist"])) \
        else dict(rel, tracklist=flat)


# --- match_albums.py:5937
# TRK-3: a position that names its disc with a hyphen ("2-3", "CD2-3"): a disc's track, never a
# movement's number within its work ("3.1", "2a")
# (TRK-6: also a video medium's name with no number - "DVD-2.1", the DVD's index of a CD + DVD -
# so the work's parts go with the DVD, not onto the CD before it)
_HYPHEN_DISC = re.compile(r"^\s*(?:(?:[A-Za-z]{1,4})?\d+|(?:dvd|bd|br|blu-?ray|hd-?dvd|vhs|video))\s*-\s*\d+", re.I)


# --- match_albums.py:5940
def flatten_tracklist(tracklist, dm, parent_position=None, movements=True):
    """Audio tracks in order. Discogs 'index' entries (a work split into
    movements) carry their audio in nested sub_tracks; headings carry none.
    The plugin's parse_discs() skips index entries, so it cannot be used
    alone for counting.

    A sub-track's own position ("2.1", "2a") numbers it WITHIN its work, not
    a disc, so it takes its parent entry's position for disc numbering."""
    out = []
    if parent_position is None and movements:
        tracklist = one_track_movements(tracklist)          # TRK-1
    for e in tracklist or []:
        if not isinstance(e, dict):
            continue
        kind = str(e.get("type_") or e.get("type") or "track").strip().casefold()
        if kind == "heading":
            continue
        if kind == "index":
            subs = flatten_tracklist(e.get("sub_tracks"), dm,
                                     parent_position=e.get("position") or "")
            if subs:
                # one work: its rows are counted as one track where they list no lengths
                n = len(out)
                # TRK-9: movements listing no lengths, the work its own ("City Life" 23:20, its five
                # movements none): the work's length, compared with its files' added up
                whole = dm._parse_duration(e.get("duration")) if not any(t.get("secs") for t in subs) else 0
                out.extend(dict(t, index=t.get("index", n), **({"work_secs": whole} if whole else {}))
                           for t in subs)
                continue
        pos = parent_position if parent_position is not None else (e.get("position") or "")
        if parent_position == "" and _HYPHEN_DISC.match(str(e.get("position") or "")):
            pos = str(e.get("position"))                   # (TRK-3: "2-3" of a work with no position)
        out.append({"position": pos, "title": e.get("title", ""),
                    "secs": dm._parse_duration(e.get("duration"))})
    return out


# --- match_albums.py:5977
_VIDEO_POS = re.compile(r"^\s*(?:video(?:\s*clip)?s?|vid|clip|v\d|dvd|bd|blu-?ray|hd-?dvd|vhs|cd-?rom|data|enh(?:anced)?|multimedia|mm)\b",
                        re.I)


# --- match_albums.py:5979
_VIDEO_TITLE = re.compile(r"\((?:video|videoclip|video clip|music video|live video|multimedia)[^)]*\)\s*$|"
                          r"^\s*(?:video|videoclip|multimedia|cd-?rom)(?:\s+(?:track|part|section|clip))?\s*[:\-]|"
                          r"\b(?:screensaver|wallpapers?|bonus multimedia|enhanced (?:part|section))\b", re.I)


# --- match_albums.py:5984
def drop_video_tracks(tracks, rel, boxed=True):
    """An enhanced CD's videos and data are listed as tracks on Discogs (Kreator -
    Endorama, Art Music AMG 099: 13 songs + 2 videos), but are never audio files. Only
    entries marked as such are dropped: a position like "Video" or "CD-ROM", or a title
    ending "(Video)", and only at the end of a release whose format says Enhanced or
    lists a DVD/CD-ROM part, so a song called "Video Killed the Radio Star" stays."""
    desc = " ".join(" ".join([f.get("name") or ""] + list(f.get("descriptions") or []))
                    for f in rel.get("formats") or []).casefold()
    if not re.search(r"enhanced|dvd|blu-?ray|cd-?rom|multimedia|video", desc):
        return tracks
    out = list(tracks)
    while out and (_VIDEO_POS.match(str(out[-1].get("position") or "")) or _VIDEO_TITLE.search(out[-1]["title"])):
        out.pop()
    # videos marked anywhere by their position ("Video 1") are never audio
    out = [t for t in out if not _VIDEO_POS.match(str(t.get("position") or ""))]
    # MED-16: a box's video discs numbered by their position ("BD1-3", "DVD2-1") beside its CDs
    # (Soft Machine - Slightly All The Time: 14 CDs and 3 Blu-rays of TV footage) - chapters,
    # never files of the CD rip, nor discs 1-3 of it. Kept where a video format says it holds
    # audio (a Blu-ray Audio, a DVD-Audio) and where nothing else would remain (MED-12)
    audio_video = _audio_video(rel)
    # (BOXED false: the rows another tagger counted for its track total, chapters among them)
    rest = [t for t in out if not _video_medium(t.get("position"), rel)]
    return rest if boxed and rest and not audio_video else out


# --- match_albums.py:6010
# a position on a video disc of a box ("DVD1-3", "BD2-1"): a chapter, never an audio file
_VIDEO_MEDIUM = re.compile(r"^\s*(?:dvd|bd|blu-?ray|hd-?dvd|vhs|video)\s*\d*\s*[-.]?\s*\d", re.I)


# --- match_albums.py:6015
# Discogs's other abbreviation of a Blu-ray's positions ("BR-1", "BR2-3"): read so only where
# the release lists a Blu-ray (Pink Floyd - The Dark Side Of The Moon Immersion, USA & Canada
# 3137117: its "BR-1".."BR-7" kept as audio tracks of the CD box, 43 for 36 files, while the
# European 3142241's "BD-1-1".. were left out - so the pressing of your copy lost the tie)
_BLURAY_POS = re.compile(r"^\s*br\s*\d*\s*[-.]?\s*\d", re.I)


# --- match_albums.py:6018
def _audio_video(rel) -> bool:
    """MED-16: a video format of the release says it holds audio (a Blu-ray Audio, a DVD-Audio):
    its positions ("BR-1", "DVD1-3") are audio tracks, never chapters."""
    return any(re.search(r"\b(?:dvd|bd|blu-?ray|hd-?dvd)\b", str(f.get("name") or ""), re.I)
               and re.search(r"audio", " ".join([str(f.get("name") or "")] +
                                                [str(d) for d in f.get("descriptions") or []]), re.I)
               for f in rel.get("formats") or [] if isinstance(f, dict))


# --- match_albums.py:6027
def _video_medium(position, rel) -> bool:
    """MED-16: the position is on a video disc of the box ("DVD1-3", "BD2-1"; "BR-1" when the
    release lists a Blu-ray)."""
    pos = str(position or "")
    if _VIDEO_MEDIUM.match(pos):
        return True
    return bool(_BLURAY_POS.match(pos)) and any(
        re.search(r"blu-?ray", str(f.get("name") or ""), re.I) for f in rel.get("formats") or [] if isinstance(f, dict))


# --- match_albums.py:6038
# a vinyl or tape side: "A", "B2", "LP-C1", '10"-A1', "MC-B2" (Kreator - Gods Of Violence box)
_SIDE_POS = re.compile(r'(?:(?:LP|MC|Cass(?:ette)?|Tape|Vinyl|\d{1,2}(?:"|\u201d|in(?:ch)?)?)\d*[-.\s])?[A-H]\d{0,2}',
                       re.I)


# --- match_albums.py:6042
_NOTES_PACKAGING = re.compile(r"\b(?:packaged|comes|housed|issued|sold)\s+in\s+(?:a\s+|an\s+)?"
                              r"(jewel[- ]?case|digi-?pa(?:c?k)|digi-?book|media-?book)", re.I)


# --- match_albums.py:6046
def discogs_club_marks(rel):
    """CLB-1: the marks a Discogs club edition (format "Club Edition") lists as printed on its
    sleeve or disc - "CRC" (Columbia House, "Back cover"), "BMG Direct" - a short word or two
    from its Other identifiers. Ring text and long notes ("Made in USA - Digital Audio Disc
    Corp.") are none. Empty for any other release."""
    club = any("club edition" in str(d).casefold() for f in rel.get("formats") or []
               for d in f.get("descriptions") or [])
    if not club:
        return []
    out = []
    for i in rel.get("identifiers") or []:
        v, where = str(i.get("value") or "").strip(), str(i.get("description") or "").casefold()
        # (a mark on the sleeve - back cover, spine, inlay - where your back cover's scan shows it;
        # never a ring or disc text, nor a sentence: "Made in USA")
        if str(i.get("type") or "").casefold() == "other" and \
                re.search(r"back|cover|sleeve|spine|inlay|insert|tray", where) and \
                not re.search(r"ring|disc|label|matrix|runout", where) and \
                re.fullmatch(r"[A-Za-z][A-Za-z&.'-]*(?: [A-Za-z][A-Za-z&.'-]*)?", v) and len(v) <= 16 and \
                not v.casefold().startswith(("made", "printed", "manufactured")) and v not in out:
            out.append(v)
    return out


# --- match_albums.py:6069
def discogs_packaging(rel):
    """A Discogs entry's packaging: its formats' descriptions, then their free text
    ("Digipak" typed there), then its notes ("Packaged in jewel case"; Sadist - Spellbound:
    Fono's jewel case and 300-copy digipak share every number)."""
    for f in rel.get("formats") or []:
        for d in list(f.get("descriptions") or []):
            if mc.packaging_kind(d):
                return mc.packaging_kind(d)
    for f in rel.get("formats") or []:
        if mc.packaging_kind(f.get("text")):
            return mc.packaging_kind(f.get("text"))
    m = _NOTES_PACKAGING.search(str(rel.get("notes") or ""))
    return mc.packaging_kind(m.group(1)) if m else ""


# --- match_albums.py:6085
# Discogs format names that are one physical disc each (qty counts the discs)
_DISC_MEDIA = {"cd", "cdr", "sacd", "dvd", "dvdr", "blu-ray", "blu-ray-r", "hd dvd", "vinyl", "minidisc"}


# --- match_albums.py:6087
# a heading that names a disc: "CD 1", "CD2", "Disc Two", "CD 2 - Instrumentals", "Bonus CD"
_DISC_HEADING = re.compile(r"^\s*(?:(?:bonus|extra|live)\s+)?(?:cd|disc|disk|dvd|sacd)(?:\s*-?\s*"
                           r"(?:\d+|one|two|three|four|five|six|seven|eight|nine|ten|[ivx]+)\b|\s*$|\s*[-:(])",
                           re.I)


# --- match_albums.py:6092
def _disc_media_total(rel):
    """How many physical discs the formats list (CD qty 1 + CD qty 1 = 2), or 0 when a
    format is not a disc (a file, a box) or names no quantity we can read."""
    total = 0
    for f in rel.get("formats") or []:
        if not isinstance(f, dict):
            return 0
        name = str(f.get("name") or "").strip().casefold()
        if name not in _DISC_MEDIA:
            if name in ("box set", "all media"):
                continue                       # the box holds the discs, it is not one
            return 0
        try:
            total += int(str(f.get("qty") or "1").strip())
        except (TypeError, ValueError):
            return 0
    return total


# --- match_albums.py:6111
def discogs_discs(rel, dm):
    """(discs, disc count) of a Discogs release: the plugin's parse_discs and
    release_disc_count, except where heading rows split the release into more discs than
    its formats hold (Feared - Reborn, 2 CDs listed "CD 1 - Album", "SIDE A", "SIDE B",
    "CD 2 - Instrumentals"). Then only a heading that names a disc starts one; the sides
    and parts under it stay on its disc, numbered on through it. Vinyl and tape keep the
    plugin's rule (their sides are real)."""
    discs = dm.parse_discs(rel)
    count = dm.release_disc_count(rel)
    media = _disc_media_total(rel)
    # MED-18: discs numbered by position prefixes ("1-01" .. "4-14") under no heading of their
    # own count one each, beside a disc listed without them (Judas Priest - Metalogy: 4 CDs as
    # one run of "1-01" .. "4-14", then a "Judas Priest Live" heading over "DVD-1" ..: the
    # headings alone made it 2 discs)
    # Only a video disc is counted so (its tracks are no disc's of a CD rip, MED-16); an audio
    # disc under a heading would be counted but its tracks left on disc 1. Vinyl and tape keep
    # the plugin's rule.
    sides = {mc.media_kind(f.get("name")) for f in rel.get("formats") or [] if isinstance(f, dict)}
    prefixed = {int(m.group(1)) for d in discs for t in d["tracks"]
                for m in [_POS_DISC.match(str(t.get("position") or ""))] if m}
    if len(prefixed) > 1 and not sides & {"vinyl", "cassette"}:
        bare = [d for d in discs if d["tracks"] and not any(
            _POS_DISC.match(str(t.get("position") or "")) for t in d["tracks"])]
        video = [d for d in bare if all(_video_medium(t.get("position"), rel) for t in d["tracks"])]
        unprefixed = len(video) if len(video) == len(bare) else None
        by_position = len(prefixed) + (unprefixed or 0)
        # (only where the formats declare that many discs: a work's sub-tracks "1.1", "2.1" on
        # one CD are no discs; and not at all beside an audio disc listed without prefixes)
        if unprefixed is not None and count < by_position <= media:
            count = by_position
    kinds = {mc.media_kind(f.get("name")) for f in rel.get("formats") or [] if isinstance(f, dict)}
    if media < 2 or len(discs) <= media or kinds & {"vinyl", "cassette"}:
        return discs, count
    if any(_POS_DISC.match(str(t.get("position") or "")) for d in discs for t in d["tracks"]):
        return discs, count                     # numbered by position prefixes, not headings
    rows = [r for r in rel.get("tracklist") or [] if isinstance(r, dict)]
    flatten = getattr(dm, "_flatten_index_entries", None)   # a work's movements, as parse_discs
    rows = flatten(rows) if flatten else rows
    out, current = [], None
    for row in rows:
        kind = str(row.get("type_") or "track").strip().casefold()
        title = str(row.get("title") or "").strip()
        if kind == "heading" and _DISC_HEADING.match(title):
            current = {"number": len(out) + 1, "title": title, "tracks": []}
            out.append(current)
        elif kind == "track":
            if current is None:
                current = {"number": 1, "title": "", "tracks": []}
                out.append(current)
            current["tracks"].append(row)
    out = [d for d in out if d["tracks"]]
    if len(out) != media:
        return discs, count                     # the headings do not say which disc is which
    for n, d in enumerate(out, start=1):
        d["number"] = n
    return out, media


# --- match_albums.py:6169
def discogs_candidate(rel, dm, whole_works=False):
    # The credit exactly as the plugin writes it (format_artist_credit honours
    # Discogs' "credited as" names and join words), plus the canonical names,
    # since files may carry either form.
    # (the rows as Discogs lists them, a work's movements each counted: what a tagger that wrote
    # the files' track total counted - _total_miscounted)
    raw_rows = len(drop_video_tracks(flatten_tracklist(rel.get("tracklist"), dm, movements=False), rel, boxed=False))
    listed = rel
    rel = discogs_one_track_movements(rel, whole_works)     # TRK-1 (the plugin's disc split too)
    artists = dm.format_artist_credit(rel.get("artists"))
    canonical = " & ".join(dm.clean_artist_name(a.get("name")) for a in rel.get("artists", [])
                           if isinstance(a, dict))
    flat = drop_video_tracks(flatten_tracklist(rel.get("tracklist"), dm), rel)
    discs, disc_count = discogs_discs(rel, dm)  # the plugin's rule, sub-headings kept on their disc
    tracks = []
    kinds = {mc.media_kind(f.get("name")) for f in rel.get("formats") or []} - {""}
    mixed_vinyl = bool(kinds & {"vinyl", "cassette"}) and bool(kinds & {"cd", "digital"})
    audio_video = _audio_video(rel)                  # (MED-16: its "BR-1" are audio tracks, as listed)
    for t in flat:
        m = _POS_DISC.match(str(t["position"]))
        tracks.append({"disc": int(m.group(1)) if m else 1, "title": t["title"], "secs": t["secs"]})
        if "index" in t:
            tracks[-1]["index"] = t["index"]          # a sub-track of an index track
            if t.get("work_secs"):
                tracks[-1]["work_secs"] = t["work_secs"]     # TRK-9: its work's length, its own none
        if not audio_video and _video_medium(t["position"], rel):
            tracks[-1]["video"] = True                # on a DVD or other video disc ("DVD1-3")
        if mixed_vinyl and _SIDE_POS.fullmatch(str(t["position"]).strip()):
            tracks[-1]["box_vinyl"] = True        # a 7" in a CD box: side A / B
    if discs and len(discs) > 1 and not any(_POS_DISC.match(str(t["position"])) for t in flat):
        # numbered by heading rows instead of position prefixes
        n = 0
        for d in discs:
            for _ in d["tracks"]:
                if n < len(tracks):
                    tracks[n]["disc"] = d["number"]
                n += 1
    # MED-11: a DVD or Blu-ray in the set (its film, its videos) is no disc of a CD rip: the
    # discs counted are those with audio tracks (Popol Vuh - Kailash, Soul Jazz: 2 CDs and a
    # DVD, scored "disc count 2 vs 3" against the 2 CDs ripped)
    audio_discs = {t["disc"] for t in tracks if not t.get("video")}
    video = any(re.search(r"\b(?:dvd|blu-?ray|hd-?dvd|vhs)\b", str(f.get("name") or ""), re.I)
                and not re.search(r"audio", " ".join(f.get("descriptions") or []), re.I)
                for f in rel.get("formats") or [])
    if video and audio_discs and len(audio_discs) < disc_count:
        disc_count = len(audio_discs)
    # MED-12: a release that is video only (the DVD of a concert, its songs listed as chapters
    # without lengths: AC/DC - Live At Donington) is no CD's (match_core.file_clues)
    video_only = bool(rel.get("formats")) and all(
        re.search(r"\b(?:dvd|blu-?ray|hd-?dvd|vhs|laserdisc|umd)\b", str(f.get("name") or ""), re.I)
        and not re.search(r"audio", " ".join([str(f.get("name") or "")] + list(f.get("descriptions") or [])), re.I)
        for f in rel.get("formats") or [])
    # a box set's discs named by the heading rows before them ("The Legacy", "The New Order")
    disc_titles, heading = {}, ""
    for row in rel.get("tracklist") or []:
        if row.get("type_") == "heading":
            heading = str(row.get("title") or "").strip()
        elif row.get("type_", "track") == "track":
            m = _POS_DISC.match(str(row.get("position") or ""))
            if m and heading and int(m.group(1)) not in disc_titles:
                disc_titles[int(m.group(1))] = heading
    labels = rel.get("labels") or []
    barcodes = {mc.norm_code(i["value"]) for i in rel.get("identifiers", [])
                if i.get("type") == "Barcode" and i.get("value")}
    year = rel.get("year") or 0
    if not year and str(rel.get("released") or "")[:4].isdigit():
        year = int(rel["released"][:4])
    # TRK-5: works listing no length, their parts lettered as one track's ("CD4-3a".."CD4-3e"
    # under "Esther's Nose Job"): the tracks read as one per work, compared only where your
    # files' discs hold exactly that (match_core.score_candidate) - never decided here
    works_view = None
    if not whole_works:
        whole = discogs_one_track_movements(listed, True)
        if whole is not listed:
            alt = discogs_candidate(listed, dm, whole_works=True)["tracks"]
            works_view = alt if len(alt) < len(tracks) else None
    return {
        **({"works_view": works_view} if works_view else {}),
        **({"whole_works": True} if whole_works else {}),
        "source": "discogs", "id": str(rel["id"]),
        "url": rel.get("uri") or f"https://www.discogs.com/release/{rel['id']}",
        "artist": artists or canonical, "artist_alt": canonical,
        # VAR-1: the artists its tracks credit (a compilation's composers: "Steve Reich", "Kyle
        # Gann" ... under performers credited on the release), each once, in order
        "track_artists": list(dict.fromkeys(
            dm.clean_artist_name(a.get("name")) for e in listed.get("tracklist") or [] if isinstance(e, dict)
            for row in [e, *(x for x in e.get("sub_tracks") or [] if isinstance(x, dict))]
            for a in row.get("artists") or [] if isinstance(a, dict) and a.get("name"))),
        "title": rel.get("title", ""), "year": year or None,
        "date": str(rel.get("released") or ""),
        "country": rel.get("country", ""),
        # CTY-2: the "Made in ..." its notes give its parts ("Made in West Germany (Booklet)")
        "notes_made_in": sorted(mc.countries_made_in(rel.get("notes") or "")),
        "label": "; ".join(sorted({dm.clean_artist_name(l.get("name")) for l in labels})),
        "catnos": {mc.norm_code(l["catno"]) for l in labels
                   if l.get("catno") and str(l["catno"]).casefold() != "none"},
        "catno_shown": ", ".join(dict.fromkeys(l["catno"] for l in labels
                                               if l.get("catno") and str(l["catno"]).casefold() != "none")),
        "barcodes": barcodes, "disc_count": disc_count, "tracks": tracks, "disc_titles": disc_titles,
        # CAT-7: the numbers it lists among its "Other" identifiers - a set's discs' own product
        # numbers ("0602557093414": Enigma - The Fall Of A Rebel Angel, disc 2) - distinctive only
        "other_codes": {k for k in (mc.norm_code(i["value"]) for i in rel.get("identifiers", [])
                                    if i.get("type") == "Other" and i.get("value"))
                        if mc.distinctive_number(k)},
        "video_only": video_only,
        "rows": raw_rows,                                   # (TRK-1: the rows before movements are one track)
        # matrix / runout, SID and label codes: compared with what the disc scans read
        "matrix": [(str(i.get("type")), str(i["value"])) for i in rel.get("identifiers", [])
                   if str(i.get("type") or "").casefold() in mc.MATRIX_KINDS and i.get("value")],
        # (EVI-8: the matrices Discogs says are on a video disc: "DVD Layer 1", "Blu-ray")
        "matrix_video": [str(i["value"]) for i in rel.get("identifiers", [])
                         if str(i.get("type") or "").casefold() in mc.MATRIX_KINDS and i.get("value")
                         and re.search(r"\b(?:dvd|blu-?ray|bd|vhs|video)\b", str(i.get("description") or ""), re.I)],
        # CLB-1: a club edition's own mark printed on its sleeve ("CRC" on the back cover: Columbia
        # House), from its identifiers - its absence from a legibly read back is evidence
        "club_marks": discogs_club_marks(rel),
        "packaging": discogs_packaging(rel),
        "formats": {k for k in (mc.media_kind(f.get("name")) for f in rel.get("formats") or []) if k},
        # the album (its master) and its format names, for Picard's preferred formats
        # (match_core.same_album, release_format_score: compared by kind only)
        "master_id": str(rel.get("master_id") or "") if rel.get("master_id") else "",
        "media_formats": discogs_format_names(rel),
        # an SACD's descriptions may name it ("CD" with "SACD", "Hybrid")
        "hires_media": mc.hires_media([f.get("name") for f in rel.get("formats") or []]
                                      + [d for f in rel.get("formats") or [] for d in f.get("descriptions") or []]),
        "sacd_media": mc.sacd_media([f.get("name") for f in rel.get("formats") or []]         # MED-3
                                    + [d for f in rel.get("formats") or [] for d in f.get("descriptions") or []]),
        "enhanced": "enhanced" in _format_words(rel),
        # a download's codecs as its format names them ("File: FLAC", "File: MP3, 320 kbps")
        "file_codecs": {d for f in rel.get("formats") or [] if str(f.get("name") or "").casefold() == "file"
                        for d in (str(x).strip().casefold() for x in f.get("descriptions") or [])
                        if d in mc.LOSSLESS_CODECS or d in mc.LOSSY_CODECS},
        # Discogs marks a bootleg "Unofficial Release" among the format's descriptions (R9:
        # Kreator - Enemy Of God Revisited, the Russian 8382890; BTBAM - Alaska)
        "unofficial": "unofficial release" in _format_words(rel),
        "genre": _genre_names(rel.get("genres") or []),
    }


# --- match_albums.py:6310
# Discogs format descriptions that make a medium a sub-format in Picard's names (a CD
# described "HDCD" is MusicBrainz's "HDCD", a vinyl described '7"' its '7" Vinyl')
_DISCOGS_SUB_FORMATS = {"hdcd": "HDCD", "shm-cd": "SHM-CD", "blu-spec cd": "Blu-spec CD", "hybrid": "Hybrid SACD",
                        "enhanced": "Enhanced CD", '7"': '7" Vinyl', '10"': '10" Vinyl', '12"': '12" Vinyl'}


# --- match_albums.py:6314
def discogs_format_names(rel):
    """Each Discogs format's name, made a sub-format's when its descriptions say so ('7"' on
    a vinyl, "HDCD" on a CD; "CDr" is "CD-R"), so a sized vinyl or special CD is never read
    as the generic "Vinyl" or "CD" your preferred formats name. [] when a format has no name."""
    out = []
    for f in rel.get("formats") or []:
        name = str(f.get("name") or "").strip()
        if not name:
            return []
        name = {"cdr": "CD-R"}.get(name.casefold(), name)
        subs = [_DISCOGS_SUB_FORMATS[d] for d in (str(x).strip().casefold() for x in f.get("descriptions") or [])
                if d in _DISCOGS_SUB_FORMATS and mc.media_kind(_DISCOGS_SUB_FORMATS[d]) == mc.media_kind(name)]
        out.append(subs[0] if subs else name)
    return out


# --- match_albums.py:6330
def _format_words(rel):
    """A Discogs release's format names, descriptions and free text, lower case, one per item."""
    return {str(x).strip().casefold() for f in rel.get("formats") or []
            for x in [f.get("name"), f.get("text"), *(f.get("descriptions") or [])] if x}


# --- match_albums.py:6560
# --------------------------------------------------------------------------
# Optional OCR
# --------------------------------------------------------------------------
IMAGE_EXT = {".jpg", ".jpeg", ".png", ".gif", ".bmp", ".webp", ".tif", ".tiff"}


# --- match_albums.py:6568
# Images that are not scans of the release: covers saved from the web, rip
# screenshots and spectrum/analysis pictures ("tech.info/Au.jpg", "ksnip_...").
_NOT_A_SCAN = re.compile(r"^(cover|folder|front|albumart\w*|thumb\w*|ksnip\S*|screenshot\S*|spectr\S*|au\d*|"
                         r"expose\d*|mv|dr|dynamic\S*|\d{2,4}x\d{2,4}\S*)$", re.I)


# --- match_albums.py:6570
_NOT_A_SCAN_DIR = re.compile(r"^(tech[ ._-]?info|info|spectr\S*|analysis|screens?(hots)?)$", re.I)


# --- match_albums.py:6575
# Pictures saved from shops and databases, not scanned from your copy: Amazon product
# images ("71-Q6hBQwTL._UF1000,1000_QL80_.jpg", "._AC_SL1500_"), Discogs release images
# ("R-4847696-1388801849-4582.jpg"). Their barcode is some other pressing's (Samael -
# Ceremony Of Opposites: the 2021 MDD reissue's, in a folder ripped in 2005).
_WEB_IMAGE = re.compile(r"\._(?:[A-Z]{2}\d|[A-Z]{2}_)|^R-\d{3,}-\d{9,}(?:-\d+)?$", re.I)


# --- match_albums.py:6578
def web_image(path):
    return bool(_WEB_IMAGE.search(Path(path).stem))


# --- match_albums.py:6582
_PHYSICAL_NAME = re.compile(r"back|rear|tray|inlay|disc|disk|(?<![a-z])cd\d*(?![a-z])|obi|matrix|spine|booklet|"
                            r"inside|insert|(?<![a-z])label|sticker|case", re.I)


# --- match_albums.py:6586
def scan_evidence(album_dir):
    """Does the folder hold scans of a physical copy (a back cover, tray card,
    booklet, disc or obi)? A download comes with a cover image at most, so such
    scans mean the disc was owned. Returns {"physical": bool, "why": str}."""
    try:
        from PIL import Image
    except ImportError:
        Image = None
    for dirpath, dirs, names in os.walk(album_dir):
        dirs[:] = [d for d in dirs if not _NOT_A_SCAN_DIR.match(d)]
        for n in sorted(names):
            p = Path(dirpath) / n
            if p.suffix.lower() not in IMAGE_EXT or p.suffix.lower() == ".gif" or _NOT_A_SCAN.match(p.stem) \
                    or web_image(p):
                continue
            if _PHYSICAL_NAME.search(p.stem):
                return {"physical": True, "why": f"a scan named {p.name}"}
            if Image is not None:
                try:
                    with Image.open(p) as im:
                        w, h = im.size
                except Exception:
                    continue
                if w >= 1000 and 1.15 <= w / max(h, 1) <= 1.5:
                    return {"physical": True, "why": f"a tray-card scan ({p.name})"}
    return {"physical": False, "why": ""}


# --- match_albums.py:6614
def packaging_evidence(album_dir):
    """The packaging your scans are named after: "scan-digipak.jpg", "Digi Cover.png",
    "Digibook 01.jpg", "Jewel case back.jpg" (Cynic - Carbon-Based Anatomy: the jewel case
    and digipak pressings share barcode and number; only the scans tell them apart).
    Returns a set of mc.packaging_kind values; empty when the names say nothing. A scan
    named "Inlay" or "Tray" (a jewel case's back card and tray) is a jewel case when no
    scan names another packaging (Sadist - Spellbound)."""
    out, jewel_parts = set(), False
    for dirpath, dirs, names in os.walk(album_dir):
        dirs[:] = [d for d in dirs if not _NOT_A_SCAN_DIR.match(d)]
        for n in names:
            p = Path(dirpath) / n
            if p.suffix.lower() in IMAGE_EXT and not web_image(p):
                k = mc.packaging_kind(p.stem)
                if k:
                    out.add(k)
                elif re.search(r"(?<![a-z])(?:inlay|tray)(?![a-z])", p.stem.casefold()):
                    jewel_parts = True
    return out or ({"jewel"} if jewel_parts else set())
